    {
      "id": "parallel-coord-encoding",
      "insight": "Encode 7 parallel axes (GDP per capita, HDI, Freedom Index, Corruption Perceptions Index, CO2 emissions per capita, Military expenditure % GDP, Internet penetration %), with each polyline representing a country colored by World Bank income group (high/upper-middle/lower-middle/low)"
    },
    {
      "id": "income-group-separation",
      "insight": "Show how the four income-group color bands separate or overlap across the seven dimensions, emphasizing where high-income and low-income polylines diverge most strongly versus where they intermingle"
    },
    {
      "id": "nonlinear-crossovers",
      "insight": "Highlight crossing patterns between adjacent axes — particularly where countries that rank high on one dimension drop sharply on the next — to reveal nonlinear relationships among development indicators"
    },
    {
      "id": "outlier-profiles",
      "insight": "Visually emphasize countries whose polyline profiles deviate dramatically from their income-group peers, such as high-income nations with unusually high carbon emissions or upper-middle-income nations with low freedom scores"
    },
    {
      "id": "corruption-freedom-cluster",
      "insight": "Draw attention to the visual clustering pattern between the Freedom Index and Corruption Perceptions Index axes, showing whether polylines remain relatively parallel or diverge between these two dimensions"
    }
  ]
}

