cat << 'EOF' > /app/generate_chart.py
import json
import asyncio
from playwright.async_api import async_playwright

with open('/app/benchmark/source_data.json', 'r') as f:
    dataset = json.load(f)

data = dataset['national_development']['data']

# Groups
groups = {
    'High': [],
    'Upper-Middle': [],
    'Lower-Middle': [],
    'Low': []
}

for row in data:
    groups[row['income_group']].append([
        row['gdp_per_capita_usd'],
        row['internet_penetration_pct'],
        row['hdi'],
        row['co2_emissions_per_capita_tons'],
        row['freedom_index'],
        row['corruption_perceptions_index'],
        row['military_expenditure_pct_gdp'],
        row['country']
    ])

html_content = f"""
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>National Development Profiles</title>
    <script src="https://cdn.jsdelivr.net/npm/echarts/dist/echarts.min.js"></script>
    <link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;600&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet">
    <style>
        :root {{
            --bg: #0f172a;
            --text: #cbd5e1;
            --title: #f8fafc;
            --border: #334155;
            --font-body: 'IBM Plex Sans', sans-serif;
            --font-mono: 'IBM Plex Mono', monospace;
        }}
        body {{
            background-color: var(--bg);
            color: var(--text);
            font-family: var(--font-body);
            margin: 0;
            padding: 40px;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            box-sizing: border-box;
        }}
        .header {{
            text-align: left;
            width: 100%;
            max-width: 1400px;
            margin-bottom: 10px;
        }}
        .title {{
            font-size: 28px;
            font-weight: 600;
            color: var(--title);
            margin: 0 0 8px 0;
        }}
        .subtitle {{
            font-size: 14px;
            color: var(--text);
            margin: 0;
            font-family: var(--font-mono);
        }}
        #chart {{
            width: 100%;
            max-width: 1400px;
            height: 700px;
            background: #1e293b;
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: 20px;
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
        }}
    </style>
</head>
<body>
    <div class="header">
        <h1 class="title">Multidimensional National Development Profiles</h1>
        <p class="subtitle">Parallel coordinates analysis of 30 countries across 7 dimensions by World Bank Income Group (approx. 2023)</p>
    </div>
    <div id="chart"></div>
    <script>
        var chartDom = document.getElementById('chart');
        var myChart = echarts.init(chartDom, 'dark', {{renderer: 'svg'}});

        var schema = [
            {{name: 'gdp', index: 0, text: 'GDP per Capita\\n(USD)', min: 0, max: 90000}},
            {{name: 'internet', index: 1, text: 'Internet Pen.\\n(%)', min: 0, max: 100}},
            {{name: 'hdi', index: 2, text: 'Human Dev. Index\\n(HDI)', min: 0.3, max: 1.0}},
            {{name: 'co2', index: 3, text: 'CO2 per Capita\\n(tons)', min: 0, max: 25}},
            {{name: 'freedom', index: 4, text: 'Freedom Index\\n(0-100)', min: 0, max: 100}},
            {{name: 'corruption', index: 5, text: 'Corruption Perceptions\\n(0-100)', min: 0, max: 100}},
            {{name: 'military', index: 6, text: 'Military Spend\\n(% GDP)', min: 0, max: 7}}
        ];

        var lineStyle = {{
            width: 2.5,
            opacity: 0.65,
            type: 'solid'
        }};

        var option = {{
            animation: false,
            backgroundColor: 'transparent',
            tooltip: {{
                padding: 10,
                backgroundColor: '#0f172a',
                borderColor: '#334155',
                borderWidth: 1,
                textStyle: {{
                    fontFamily: "'IBM Plex Mono', monospace",
                    fontSize: 12,
                    color: '#f8fafc'
                }},
                formatter: function (params) {{
                    var data = params.data;
                    return '<strong style="color:' + params.color + ';">' + data[7] + '</strong><br/>'
                         + 'GDP: $' + data[0] + '<br/>'
                         + 'Internet: ' + data[1] + '%<br/>'
                         + 'HDI: ' + data[2] + '<br/>'
                         + 'CO2: ' + data[3] + ' tons<br/>'
                         + 'Freedom: ' + data[4] + '<br/>'
                         + 'Corruption: ' + data[5] + '<br/>'
                         + 'Military: ' + data[6] + '%';
                }}
            }},
            legend: {{
                bottom: 10,
                itemGap: 30,
                textStyle: {{
                    fontFamily: "'IBM Plex Sans', sans-serif",
                    fontSize: 14,
                    color: '#cbd5e1'
                }},
                data: ['High Income', 'Upper-Middle Income', 'Lower-Middle Income', 'Low Income']
            }},
            parallelAxis: [
                {{dim: 0, name: schema[0].text, min: schema[0].min, max: schema[0].max}},
                {{dim: 1, name: schema[1].text, min: schema[1].min, max: schema[1].max}},
                {{dim: 2, name: schema[2].text, min: schema[2].min, max: schema[2].max}},
                {{dim: 3, name: schema[3].text, min: schema[3].min, max: schema[3].max}},
                {{dim: 4, name: schema[4].text, min: schema[4].min, max: schema[4].max}},
                {{dim: 5, name: schema[5].text, min: schema[5].min, max: schema[5].max}},
                {{dim: 6, name: schema[6].text, min: schema[6].min, max: schema[6].max}}
            ].map(function (item) {{
                return Object.assign(item, {{
                    nameTextStyle: {{
                        fontFamily: "'IBM Plex Sans', sans-serif",
                        fontSize: 13,
                        color: '#94a3b8',
                        padding: [0, 0, 10, 0]
                    }},
                    axisLabel: {{
                        fontFamily: "'IBM Plex Mono', monospace",
                        color: '#64748b'
                    }},
                    axisLine: {{
                        lineStyle: {{
                            color: '#475569'
                        }}
                    }},
                    splitLine: {{
                        show: false
                    }}
                }});
            }}),
            parallel: {{
                left: '4%',
                right: '4%',
                bottom: '12%',
                top: '10%',
                parallelAxisDefault: {{
                    type: 'value',
                    nameLocation: 'end',
                    nameGap: 20
                }}
            }},
            color: ['#0ea5e9', '#10b981', '#f59e0b', '#f43f5e'],
            series: [
                {{
                    name: 'High Income',
                    type: 'parallel',
                    lineStyle: lineStyle,
                    data: {json.dumps(groups['High'])}
                }},
                {{
                    name: 'Upper-Middle Income',
                    type: 'parallel',
                    lineStyle: lineStyle,
                    data: {json.dumps(groups['Upper-Middle'])}
                }},
                {{
                    name: 'Lower-Middle Income',
                    type: 'parallel',
                    lineStyle: lineStyle,
                    data: {json.dumps(groups['Lower-Middle'])}
                }},
                {{
                    name: 'Low Income',
                    type: 'parallel',
                    lineStyle: lineStyle,
                    data: {json.dumps(groups['Low'])}
                }}
            ]
        }};

        myChart.setOption(option);
    </script>
</body>
</html>
"""

with open('/app/chart.html', 'w') as f:
    f.write(html_content)

async def capture():
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        page = await browser.new_page(viewport={"width": 1600, "height": 900}, device_scale_factor=2)
        await page.goto("file:///app/chart.html", wait_until="networkidle")
        # Ensure fonts are loaded
        await page.evaluate("document.fonts.ready")
        await page.screenshot(path='/app/output/result.png')
        await browser.close()

asyncio.run(capture())
